WITH supplier_totals AS (SELECT supplier_id, SORT_ARRAY(COLLECT_SET(brand)) brand_list, ROUND((100 * SUM(CASE WHEN category = 'Electronics' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_electronics FROM products GROUP BY supplier_id) SELECT s.id, s.country, st.brand_list, st.pct_electronics FROM suppliers s LEFT JOIN supplier_totals st ON s.id = st.supplier_id WHERE st.pct_electronics >= 61
